/* gohud icon catalog — the "Find an icon" section of icons.html.
 *
 * Data: `site/icons.js` (`window.GOHUD_ICONS`), generated by tools/make_icons_page.py from the icon sets —
 *   icons  [name, set, group key, "search words", inner SVG]   in display order
 *   groups [key, title]                                         titles stay English: they sit next to the key code uses
 *   aliases {alias: name}                                       the same aliases `GoIconSet` follows
 * Words: the `data-*` attributes of #icon-catalog — the generator writes them in the page's language.
 *
 * 🔑 The ranking is the one `GoIconSet.search()` uses (core/go_icon_set.gd): the whole name, then a name one of
 *    whose aliases is the query, then a whole word, the start of a word, anywhere in the name; a match in the
 *    name beats one in an alias, which beats one in the search words. Every word has to match.
 * 🛑 Never render all 1,287 at once — 120 at a time, "Show more" for the next 120.
 * 🛑 The CSS lives in the `.icat` rules of site/style.css (this file injects no styles).
 */
(function () {
  'use strict';

  var root = document.getElementById('icon-catalog');
  var data = window.GOHUD_ICONS;
  if (!root || !data) return;

  var PAGE = 120;
  var lang = document.documentElement.lang || 'en';
  var say = function (key) { return root.getAttribute('data-' + key) || ''; };
  var fmt = function (value) {
    try { return new Intl.NumberFormat(lang).format(value); } catch (e) { return String(value); }
  };
  var CLASS = { default: 'GoIconSet', game: 'GoGameIcons', library: 'GoIconLibrary' };
  var TURN_ON = {
    game: 'GoUi.add_icons(GoGameIcons.icon_set())',
    library: 'GoUi.add_icons(GoIconLibrary.icon_set())',
    medieval: 'GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK)'
  };

  var input = root.querySelector('#icat-q');
  var picker = root.querySelector('#icat-g');
  var grid = root.querySelector('.icat-grid');
  var count = root.querySelector('.icat-count');
  var more = root.querySelector('.icat-more');
  var detail = root.querySelector('.icat-detail');
  var setButtons = Array.prototype.slice.call(root.querySelectorAll('.icat-sets button'));
  var setTitle = {};
  setButtons.forEach(function (b) { setTitle[b.getAttribute('data-set')] = b.getAttribute('data-title'); });
  var groupTitle = {};
  data.groups.forEach(function (g) { groupTitle[g[0]] = g[1]; });
  var aliasesOf = {};
  Object.keys(data.aliases).forEach(function (alias) {
    var name = data.aliases[alias];
    (aliasesOf[name] = aliasesOf[name] || []).push(alias);
  });

  var state = { set: '', group: '', words: [], whole: '', shown: PAGE, picked: -1 };
  var matches = [];

  function esc(text) {
    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function svg(icon, size) {
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="' + size + '" height="' + size + '" ' +
      (data.heads[icon[1]] || '') + ' aria-hidden="true" focusable="false">' + icon[4] + '</svg>';
  }

  // How well one term matches a name split into words — the same steps as GoIconSet._match().
  function match(term, parts, whole, word, start, inside) {
    if (whole === term) return word + 20;
    if (parts.indexOf(term) >= 0) return word;
    for (var i = 0; i < parts.length; i++) if (parts[i].indexOf(term) === 0) return start;
    return inside > 0 && whole.indexOf(term) >= 0 ? inside : 0;
  }

  function score(icon) {
    var name = icon[0];
    var aliases = aliasesOf[name] || [];
    var tags = icon[3] ? icon[3].split(' ') : [];
    var total = name === state.whole ? 1000 : (aliases.indexOf(state.whole) >= 0 ? 500 : 0);
    for (var i = 0; i < state.words.length; i++) {
      var term = state.words[i];
      var best = match(term, name.split('_'), name, 60, 40, 25);
      for (var a = 0; a < aliases.length; a++) best = Math.max(best, match(term, aliases[a].split('_'), aliases[a], 30, 20, 10));
      for (var t = 0; t < tags.length; t++) best = Math.max(best, match(term, [tags[t]], tags[t], 20, 12, 0));
      if (icon[2] === term) best = Math.max(best, 10);
      if (!best) return 0;
      total += best;
    }
    return total;
  }

  function inSet(icon) { return !state.set || icon[1] === state.set; }

  function fillGroups() {
    var counts = {};
    data.icons.forEach(function (icon) { if (inSet(icon)) counts[icon[2]] = (counts[icon[2]] || 0) + 1; });
    var keep = state.group && counts[state.group] ? state.group : '';
    var options = ['<option value="">' + esc(say('all-groups')) + '</option>'];
    data.groups.forEach(function (g) {
      if (counts[g[0]]) options.push('<option value="' + esc(g[0]) + '">' + esc(g[1]) + ' (' + fmt(counts[g[0]]) + ')</option>');
    });
    picker.innerHTML = options.join('');
    picker.value = keep;
    state.group = keep;
  }

  function filter() {
    matches = [];
    data.icons.forEach(function (icon, index) {
      if (!inSet(icon) || (state.group && icon[2] !== state.group)) return;
      var value = state.words.length ? score(icon) : 1;
      if (value) matches.push([value, index]);
    });
    if (state.words.length) {
      matches.sort(function (a, b) {
        return b[0] - a[0] || (data.icons[a[1]][0] < data.icons[b[1]][0] ? -1 : 1);
      });
    }
    state.shown = PAGE;
    render();
  }

  function render() {
    var html = [];
    var end = Math.min(state.shown, matches.length);
    for (var i = 0; i < end; i++) {
      var index = matches[i][1];
      var icon = data.icons[index];
      html.push('<button type="button" data-i="' + index + '" aria-pressed="' + (index === state.picked) + '" title="' +
        esc(setTitle[icon[1]] + ' · ' + (groupTitle[icon[2]] || icon[2])) + '">' + svg(icon, 28) +
        '<span>' + esc(icon[0]) + '</span></button>');
    }
    grid.innerHTML = html.join('');
    count.textContent = matches.length ? say('count').replace('{n}', fmt(matches.length)) : say('empty');
    more.hidden = end >= matches.length;
  }

  function code(line) {
    return '<pre><code>' + esc(line) + '</code></pre>';
  }

  function pick(index) {
    state.picked = index;
    var icon = data.icons[index];
    var name = icon[0];
    var constant = CLASS[icon[1]] ? CLASS[icon[1]] + '.' + name.toUpperCase() : '&"' + name + '"';
    var aliases = aliasesOf[name] || [];
    var lines = [
      '<div class="icat-pic">' + svg(icon, 48) + '</div>',
      '<div class="icat-meta"><code class="icat-name">' + esc(name) + '</code>' +
        (aliases.length ? ' <span class="icat-aka">= ' + aliases.map(esc).join(' · ') + '</span>' : '') +
        '<br><span>' + esc(setTitle[icon[1]]) + ' · ' + esc(groupTitle[icon[2]] || icon[2]) + '</span></div>',
      '<button type="button" class="btn icat-copy" data-name="' + esc(name) + '">' + esc(say('copy')) + '</button>',
      '<div class="icat-code">' + code('GoUi.icons().node(' + constant + ', 24)') +
        (TURN_ON[icon[1]] ? '<p>' + esc(icon[1] === 'medieval' ? say('preset') : say('needs')) + '</p>' + code(TURN_ON[icon[1]])
                          : '<p>' + esc(say('always')) + '</p>') + '</div>'
    ];
    detail.innerHTML = lines.join('');
    detail.hidden = false;
    Array.prototype.forEach.call(grid.querySelectorAll('button[aria-pressed="true"]'), function (b) {
      b.setAttribute('aria-pressed', 'false');
    });
    var pressed = grid.querySelector('button[data-i="' + index + '"]');
    if (pressed) pressed.setAttribute('aria-pressed', 'true');
  }

  function copy(text, button) {
    var done = function () {
      var label = button.textContent;
      button.textContent = say('copied');
      button.classList.add('done');
      setTimeout(function () { button.textContent = label; button.classList.remove('done'); }, 1400);
    };
    var fallback = function () {
      var area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.opacity = '0';
      document.body.appendChild(area);
      area.select();
      try { document.execCommand('copy'); done(); } catch (e) { /* the name stays selectable on screen */ }
      document.body.removeChild(area);
    };
    // 🛑 `navigator.clipboard` is refused on file:// and plain http — the old way covers both.
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, fallback);
    } else {
      fallback();
    }
  }

  var typing;
  input.addEventListener('input', function () {
    clearTimeout(typing);
    typing = setTimeout(function () {
      var words = input.value.toLowerCase().replace(/[-_]/g, ' ').split(/\s+/).filter(Boolean);
      state.words = words;
      state.whole = words.join('_');
      filter();
    }, 90);
  });
  picker.addEventListener('change', function () { state.group = picker.value; filter(); });
  setButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      state.set = button.getAttribute('data-set');
      setButtons.forEach(function (b) { b.setAttribute('aria-pressed', String(b === button)); });
      fillGroups();
      filter();
    });
  });
  grid.addEventListener('click', function (event) {
    var button = event.target.closest('button[data-i]');
    if (button) pick(Number(button.getAttribute('data-i')));
  });
  more.addEventListener('click', function () {
    state.shown += PAGE;
    render();
    var next = grid.querySelectorAll('button')[state.shown - PAGE];
    if (next) next.focus();
  });
  detail.addEventListener('click', function (event) {
    var button = event.target.closest('.icat-copy');
    if (button) copy(button.getAttribute('data-name'), button);
  });

  fillGroups();
  filter();
})();
